type FastInput struct {
	reader *bufio.Reader
	buf    []byte
	bufLen int
	bufOff int
	next   int
}

func NewFastInput(r *bufio.Reader) *FastInput {
	return &FastInput{
		reader: r,
		buf:    make([]byte, 1<<13),
	}
}

func (f *FastInput) read() int {
	for f.bufLen == f.bufOff {
		f.bufOff = 0
		n, err := f.reader.Read(f.buf)
		if err != nil {
			f.bufLen = -1
			return -1
		}
		f.bufLen = n
		if f.bufLen == -1 {
			return -1
		}
	}
	c := f.buf[f.bufOff]
	f.bufOff++
	return int(c)
}

func (f *FastInput) skipBlank() {
	for f.next >= 0 && f.next <= 32 {
		f.next = f.read()
	}
}

func (f *FastInput) ReadInt() int {
	sign := 1
