	if f.next == '+' || f.next == '-' {
		if f.next == '-' {
			sign = -1
		}
		f.next = f.read()
	}

	val := 0
	if sign == 1 {
		for f.next >= '0' && f.next <= '9' {
			val = val*10 + f.next - '0'
			f.next = f.read()
		}
	} else {
		for f.next >= '0' && f.next <= '9' {
			val = val*10 - f.next + '0'
			f.next = f.read()
		}
	}

	return val
}

